selector_to_html = {"a[href=\"#pyskyfire.ducts.path.Path.s\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.Path.s\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">s</span></span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.path.Path.refined\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.Path.refined\">\n<span class=\"sig-name descname\"><span class=\"pre\">refined</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">max_step</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Split distributed connections, retaining exact generated arc geometry.</p><p>Manually supplied Continuous connections without a center and normal\nmust already be resolved finely enough; their centerline is interpolated\nlinearly while their supplied arc length and curvature are retained.</p></dd>", "a[href=\"#pyskyfire.ducts.path.Path.from_curve\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.Path.from_curve\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_curve</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">curve</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">t_span</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">max_turn</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">math.radians(5.0)</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Sample a curve-like object into stations, as finely as its bends need.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">curve</span></code> is anything that maps a parameter <code class=\"docutils literal notranslate\"><span class=\"pre\">t</span></code> to a point: called\nwith an array of parameters it returns points of shape <code class=\"docutils literal notranslate\"><span class=\"pre\">(len(t),</span> <span class=\"pre\">3)</span></code>,\nor it returns one point per scalar <code class=\"docutils literal notranslate\"><span class=\"pre\">t</span></code>. SciPy\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">CubicSpline</span></code>,\n<code class=\"docutils literal notranslate\"><span class=\"pre\">make_interp_spline</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">PchipInterpolator</span></code> qualify as they are, and\nso does a plain function. Planar points <code class=\"docutils literal notranslate\"><span class=\"pre\">(len(t),</span> <span class=\"pre\">2)</span></code> lie in the x-y\nplane. <code class=\"docutils literal notranslate\"><span class=\"pre\">t_span</span></code> is the <code class=\"docutils literal notranslate\"><span class=\"pre\">(start,</span> <span class=\"pre\">end)</span></code> parameter range to follow.</p><p>Sampling is adaptive. Any interval whose curve turns by more than\n<code class=\"docutils literal notranslate\"><span class=\"pre\">max_turn</span></code> [rad] is halved, so stations crowd into tight bends and\nstay sparse along straight stretches. Each interval then becomes the\ncircular arc through its two stations and the curve\u2019s own midpoint: a\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Continuous</span></code> carrying that arc\u2019s radius, length, center, and\nnormal, or a <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Straight</span></code> where the three are collinear.</p></dd>", "a[href=\"#pyskyfire-ducts-path-path\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.path.Path<a class=\"headerlink\" href=\"#pyskyfire-ducts-path-path\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.ducts.path.Path.__post_init__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.Path.__post_init__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__post_init__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.path.Path.curvature_radius\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.Path.curvature_radius\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">curvature_radius</span></span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.path.Path.from_nodes\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.Path.from_nodes\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_nodes</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">nodes</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.path.Path.tangents\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.Path.tangents\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">tangents</span></span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.path.Path.centerline\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.Path.centerline\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">centerline</span></span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.path.Path\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.Path\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.path.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Path</span></span></dt><dd><p>Resolved stations and connections in order from inlet to outlet.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">s</span></code> is true arc length [m]. Geometry carries no bore diameter or state.\nUse <a class=\"reference internal\" href=\"#pyskyfire.ducts.path.Path.refined\" title=\"pyskyfire.ducts.path.Path.refined\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">refined()</span></code></a> to choose the thermal/flow integration resolution.</p></dd>", "a[href=\"#pyskyfire.ducts.path.Path.lengths\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.Path.lengths\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">lengths</span></span></dt><dd></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
